#[derive(Clone, Debug)]
struct CaptureLifecycleState {
    phase: &'static str,
    desired_running: bool,
    autostart: bool,
    pid: Option<u32>,
    started_at: Option<u128>,
    ready_at: Option<u128>,
    last_exit_at: Option<u128>,
    last_exit_code: Option<i32>,
    last_error: String,
    restart_count: u32,
    consecutive_failures: u32,
    unhealthy_confirmations: u32,
    restart_budget: u32,
    next_restart_at: Option<u128>,
}

impl CaptureLifecycleState {
    fn new(provider: CaptureProvider) -> Self {
        let autostart = provider.is_embedded()
            || (provider.is_managed()
                && env::var("STEEL_CAPTURE_SERVICE_AUTOSTART").as_deref() != Ok("0"));
        Self::with_policy(provider, true, autostart)
    }

    fn with_policy(provider: CaptureProvider, enabled: bool, autostart: bool) -> Self {
        let autostart = enabled && autostart;
        let embedded_ready = enabled && provider.is_embedded();
        Self {
            phase: if !enabled {
                "disabled"
            } else if provider.is_embedded() {
                "ready"
            } else if autostart {
                "starting"
            } else {
                "stopped"
            },
            desired_running: embedded_ready || autostart,
            autostart,
            pid: None,
            started_at: None,
            ready_at: embedded_ready.then(current_time_millis),
            last_exit_at: None,
            last_exit_code: None,
            last_error: String::new(),
            restart_count: 0,
            consecutive_failures: 0,
            unhealthy_confirmations: 0,
            restart_budget: capture_restart_budget(),
            next_restart_at: None,
        }
    }
}

