fn build_config_json(capture_port: u16) -> String {
    build_config_json_for(capture_port, CaptureProvider::from_env())
}

fn build_config_json_for(capture_port: u16, provider: CaptureProvider) -> String {
    let origin = capture_origin(capture_port);
    json!({
        "service": {
            "name": "steel-inspection-service",
            "role": "api-config-capture-orchestrator",
            "capturePort": capture_port,
            "captureOrigin": origin,
            "captureProvider": provider.as_str(),
            "captureManaged": provider.is_managed(),
            "updatedAt": current_time_string()
        },
        "capture": {
            "mode": "eight-camera",
            "driver": "lvm-nvt",
            "provider": provider.as_str(),
            "fallback": "simulated",
            "cameras": default_capture_cameras_value()
        }
    })
    .to_string()
}

fn simulated_provider_string_field(payload: &Value, keys: &[&str]) -> String {
    keys.iter()
        .find_map(|key| payload.get(*key))
        .and_then(|value| {
            value
                .as_str()
                .map(str::to_string)
                .or_else(|| value.as_i64().map(|item| item.to_string()))
        })
        .unwrap_or_default()
}

impl CaptureServiceManager {
    fn new(
        port: u16,
        provider: CaptureProvider,
        capture: &runtime_profile::RuntimeCapture,
    ) -> Self {
        let origin = capture_origin(port);
        let host = capture_host_from_origin(&origin).unwrap_or_else(|| "127.0.0.1".to_string());
        let port = capture_port_from_origin(&origin).unwrap_or(port);
        let manager = Self {
            host,
            port,
            origin,
            provider,
            process: Mutex::new(None),
            lifecycle: Mutex::new(CaptureLifecycleState::with_policy(
                provider,
                capture.enabled,
                capture.autostart,
            )),
            supervisor_shutdown: AtomicBool::new(false),
            simulated_capture_mode: Mutex::new("continuous".to_string()),
            simulated_continuous_line_rate: Mutex::new(300.0),
        };
        manager
    }

    fn start_supervisor(manager: &Arc<Self>) {
        manager.supervisor_tick();
        let weak = Arc::downgrade(manager);
        let _ = std::thread::Builder::new()
            .name("capture-service-supervisor".to_string())
            .spawn(move || loop {
                std::thread::sleep(Duration::from_millis(CAPTURE_SUPERVISOR_POLL_MS));
                let Some(manager) = weak.upgrade() else {
                    break;
                };
                if manager.supervisor_shutdown.load(Ordering::Acquire) {
                    break;
                }
                manager.supervisor_tick();
            });
    }

    fn spawn_managed_process(&self) -> Result<u32, String> {
        let Some(exe) = find_capture_service_exe() else {
            return Err("capture executable not found".to_string());
        };
        let log_root = env::var("STEEL_RUNTIME_LOG_DIR")
            .map(PathBuf::from)
            .unwrap_or_else(|_| config_dir().join("logs"));
        fs::create_dir_all(&log_root)
            .map_err(|error| format!("capture log directory failed: {error}"))?;
        let capture_log_path = log_root.join("capture-child.log");
        let capture_log = fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&capture_log_path)
            .map_err(|error| format!("capture log open failed: {error}"))?;
        let capture_error_log = capture_log
            .try_clone()
            .map_err(|error| format!("capture log clone failed: {error}"))?;
        let mut command = Command::new(&exe);
        command
            .arg("--port")
            .arg(self.port.to_string())
            .current_dir(exe.parent().unwrap_or_else(|| Path::new(".")))
            .stdin(Stdio::null())
            .stdout(Stdio::from(capture_log))
            .stderr(Stdio::from(capture_error_log));
        let child = controlled_process::ManagedChild::spawn(&mut command)
            .map_err(|error| format!("capture spawn failed: {error:?}"))?;
        let pid = child.id();
        self.process
            .lock()
            .map_err(|_| "capture process lock poisoned".to_string())?
            .replace(child);
        Ok(pid)
    }

    fn schedule_restart(&self, error: String, exit_code: Option<i32>) {
        let now = current_time_millis();
        if let Ok(mut lifecycle) = self.lifecycle.lock() {
            lifecycle.pid = None;
            lifecycle.ready_at = None;
            lifecycle.last_exit_at = Some(now);
            lifecycle.last_exit_code = exit_code;
            lifecycle.last_error = error;
            lifecycle.consecutive_failures = lifecycle.consecutive_failures.saturating_add(1);
            lifecycle.unhealthy_confirmations = 0;
            if !lifecycle.desired_running {
                lifecycle.phase = "stopped";
                lifecycle.next_restart_at = None;
                return;
            }
            lifecycle.phase = "degraded";
            if lifecycle.consecutive_failures >= lifecycle.restart_budget {
                lifecycle.next_restart_at = None;
                return;
            }
            let exponent = lifecycle.consecutive_failures.saturating_sub(1).min(10);
            let delay = capture_restart_backoff_ms()
                .saturating_mul(1_u64 << exponent)
                .min(CAPTURE_RESTART_BACKOFF_MAX_MS);
            lifecycle.next_restart_at = Some(now.saturating_add(u128::from(delay)));
        }
    }

    fn supervisor_tick(&self) {
        if self.supervisor_shutdown.load(Ordering::Acquire) {
            return;
        }

        // In the packaged runtime the Windows Supervisor owns the capture child.
        // The business service remains a read-only proxy for its health and API.
        if env::var("STEEL_CAPTURE_MANAGED_BY_SUPERVISOR").as_deref() == Ok("1") {
            let listening = self.endpoint_listening();
            if let Ok(mut lifecycle) = self.lifecycle.lock() {
                lifecycle.desired_running = true;
                lifecycle.phase = if listening { "ready" } else { "degraded" };
                lifecycle.pid = None;
                if listening {
                    lifecycle.ready_at.get_or_insert_with(current_time_millis);
                    lifecycle.last_error.clear();
                } else {
                    lifecycle.ready_at = None;
                    lifecycle.last_error =
                        "capture endpoint unavailable (owned by runtime supervisor)".to_string();
                }
            }
            return;
        }

        if self.provider.is_embedded() {
            if let Ok(mut lifecycle) = self.lifecycle.lock() {
                lifecycle.phase = if lifecycle.desired_running {
                    "ready"
                } else {
                    "stopped"
                };
                if lifecycle.desired_running {
                    lifecycle.ready_at.get_or_insert_with(current_time_millis);
                } else {
                    lifecycle.ready_at = None;
                }
                lifecycle.last_error.clear();
            }
            return;
        }

        if !self.provider.is_managed() {
            let listening = self.endpoint_listening();
            if let Ok(mut lifecycle) = self.lifecycle.lock() {
                lifecycle.desired_running = true;
                lifecycle.phase = if listening { "ready" } else { "degraded" };
                if listening {
                    lifecycle.ready_at.get_or_insert_with(current_time_millis);
                } else {
                    lifecycle.ready_at = None;
                }
                lifecycle.last_error = if listening {
                    String::new()
                } else {
                    "external capture endpoint unavailable".to_string()
                };
            }
            return;
        }

        let mut exited = None;
        let mut wait_error = None;
        let mut running_pid = None;
        if let Ok(mut process) = self.process.lock() {
            if let Some(child) = process.as_mut() {
                running_pid = Some(child.id());
                match child.try_wait() {
                    Ok(Some(status)) => {
                        exited = Some(status.code());
                        process.take();
                        running_pid = None;
                    }
                    Ok(None) => {}
                    Err(error) => {
                        wait_error = Some(format!("capture wait failed: {error:?}"));
                        if let Some(mut child) = process.take() {
                            let _ = child.terminate();
                        }
                        running_pid = None;
                    }
                }
            }
        }

        if let Some(error) = wait_error {
            self.schedule_restart(error, None);
            return;
        }
        if let Some(exit_code) = exited {
            self.schedule_restart(
                format!(
                    "capture process exited with code {}",
                    exit_code.unwrap_or(-1)
                ),
                exit_code,
            );
            return;
        }

        if let Some(pid) = running_pid {
            let listening = self.endpoint_listening();
            let now = current_time_millis();
            let timed_out = self
                .lifecycle
                .lock()
                .ok()
                .and_then(|lifecycle| lifecycle.started_at)
                .is_some_and(|started_at| {
                    now.saturating_sub(started_at) > u128::from(capture_ready_timeout_ms())
                });
            if listening {
                let restart_required = self
                    .probe_response("/health", Duration::from_millis(1_500))
                    .and_then(|response| serde_json::from_slice::<Value>(&response.body).ok())
                    .is_some_and(|health| {
                        health
                            .get("restartRequired")
                            .and_then(Value::as_bool)
                            .or_else(|| {
                                health
                                    .get("sdkCaptureState")
                                    .and_then(|state| state.get("restartRequired"))
                                    .and_then(Value::as_bool)
                            })
                            == Some(true)
                    });
                let confirmed_restart = self.lifecycle.lock().ok().is_some_and(|mut lifecycle| {
                    lifecycle.unhealthy_confirmations = if restart_required {
                        lifecycle.unhealthy_confirmations.saturating_add(1)
                    } else {
                        0
                    };
                    lifecycle.unhealthy_confirmations >= 2
                });
                if confirmed_restart {
                    if let Ok(mut process) = self.process.lock() {
                        if let Some(mut child) = process.take() {
                            let _ = child.terminate();
                        }
                    }
                    self.schedule_restart(
                        "capture provider requested process restart".to_string(),
                        None,
                    );
                    return;
                }
                if let Ok(mut lifecycle) = self.lifecycle.lock() {
                    lifecycle.phase = "ready";
                    lifecycle.pid = Some(pid);
                    lifecycle.ready_at.get_or_insert(now);
                    lifecycle.last_error.clear();
                    if lifecycle.started_at.is_some_and(|started_at| {
                        now.saturating_sub(started_at) >= CAPTURE_RESTART_STABLE_MS
                    }) {
                        lifecycle.consecutive_failures = 0;
                    }
                    lifecycle.next_restart_at = None;
                }
            } else if timed_out {
                if let Ok(mut process) = self.process.lock() {
                    if let Some(mut child) = process.take() {
                        let _ = child.terminate();
                    }
                }
                self.schedule_restart("capture readiness timeout".to_string(), None);
            } else if let Ok(mut lifecycle) = self.lifecycle.lock() {
                lifecycle.phase = "starting";
                lifecycle.pid = Some(pid);
            }
            return;
        }

        if self.endpoint_listening() {
            if let Ok(mut lifecycle) = self.lifecycle.lock() {
                lifecycle.phase = "ready";
                lifecycle.pid = None;
                lifecycle.ready_at.get_or_insert(current_time_millis());
                lifecycle.last_error.clear();
                lifecycle.consecutive_failures = 0;
                lifecycle.next_restart_at = None;
            }
            return;
        }

        let now = current_time_millis();
        let should_spawn = self.lifecycle.lock().ok().is_some_and(|lifecycle| {
            lifecycle.desired_running
                && lifecycle.consecutive_failures < lifecycle.restart_budget
                && lifecycle.next_restart_at.is_none_or(|next| now >= next)
        });
        if !should_spawn {
            return;
        }

        match self.spawn_managed_process() {
            Ok(pid) => {
                if let Ok(mut lifecycle) = self.lifecycle.lock() {
                    lifecycle.phase = "starting";
                    lifecycle.pid = Some(pid);
                    lifecycle.started_at = Some(now);
                    lifecycle.ready_at = None;
                    lifecycle.next_restart_at = None;
                    lifecycle.restart_count = lifecycle.restart_count.saturating_add(1);
                }
            }
            Err(error) => self.schedule_restart(error, None),
        }
    }

    fn wait_for_ready(&self, timeout: Duration) -> bool {
        let deadline = Instant::now() + timeout;
        while Instant::now() < deadline {
            self.supervisor_tick();
            if self.is_running() {
                return true;
            }
            let exhausted = self.lifecycle.lock().ok().is_some_and(|lifecycle| {
                lifecycle.consecutive_failures >= lifecycle.restart_budget
            });
            if exhausted {
                return false;
            }
            std::thread::sleep(Duration::from_millis(100));
        }
        false
    }

    fn start(&self) -> bool {
        if self.provider == CaptureProvider::Bkv {
            return true;
        }
        if let Ok(mut lifecycle) = self.lifecycle.lock() {
            lifecycle.desired_running = true;
            lifecycle.phase = "starting";
            lifecycle.consecutive_failures = 0;
            lifecycle.next_restart_at = None;
            lifecycle.last_error.clear();
        }
        if self.provider.is_embedded() {
            self.supervisor_tick();
            return true;
        }
        if !self.provider.is_managed() {
            self.supervisor_tick();
            return self.endpoint_listening();
        }
        self.wait_for_ready(Duration::from_millis(capture_ready_timeout_ms()))
    }

    fn stop(&self) -> bool {
        if env::var("STEEL_CAPTURE_MANAGED_BY_SUPERVISOR").as_deref() == Ok("1") {
            return true;
        }
        if self.provider == CaptureProvider::Bkv {
            return true;
        }
        if let Ok(mut lifecycle) = self.lifecycle.lock() {
            lifecycle.desired_running = false;
            lifecycle.phase = "stopping";
            lifecycle.next_restart_at = None;
        }
        if self.provider.is_embedded() {
            self.supervisor_tick();
            return true;
        }
        if !self.provider.is_managed() {
            self.supervisor_tick();
            return !self.endpoint_listening();
        }
        if let Ok(mut process) = self.process.lock() {
            if let Some(mut child) = process.take() {
                let _ = child.terminate();
            }
        }
        let deadline = Instant::now() + Duration::from_secs(3);
        while self.endpoint_listening() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(100));
        }
        let stopped = !self.endpoint_listening();
        if let Ok(mut lifecycle) = self.lifecycle.lock() {
            lifecycle.phase = if stopped { "stopped" } else { "degraded" };
            lifecycle.pid = None;
            lifecycle.ready_at = None;
            if !stopped {
                lifecycle.last_error = "capture endpoint remained available after stop".to_string();
            }
        }
        stopped
    }

    fn restart(&self) -> bool {
        let _ = self.stop();
        self.start()
    }

    fn shutdown(&self) {
        if env::var("STEEL_CAPTURE_MANAGED_BY_SUPERVISOR").as_deref() == Ok("1") {
            self.supervisor_shutdown.store(true, Ordering::Release);
            return;
        }
        let _ = self.stop();
        self.supervisor_shutdown.store(true, Ordering::Release);
    }

    fn endpoint_listening(&self) -> bool {
        capture_service_listening_at(&self.host, self.port)
    }

    fn is_running(&self) -> bool {
        self.lifecycle
            .lock()
            .map(|lifecycle| matches!(lifecycle.phase, "ready" | "collecting"))
            .unwrap_or(false)
    }

    fn set_collecting(&self, collecting: bool) {
        if let Ok(mut lifecycle) = self.lifecycle.lock() {
            if collecting && lifecycle.phase == "ready" {
                lifecycle.phase = "collecting";
            } else if !collecting && lifecycle.phase == "collecting" {
                lifecycle.phase = "ready";
            }
        }
    }

    fn status_json(&self) -> String {
        let exe = find_capture_service_exe()
            .map(|path| path.display().to_string())
            .unwrap_or_default();
        let lifecycle = self
            .lifecycle
            .lock()
            .map(|value| value.clone())
            .unwrap_or_else(|_| CaptureLifecycleState::new(self.provider));
        let running = matches!(lifecycle.phase, "ready" | "collecting");
        let process_available = match self.provider {
            CaptureProvider::HeadlessCpp => !exe.is_empty(),
            CaptureProvider::ExternalApi => true,
            CaptureProvider::Simulated => false,
            CaptureProvider::Bkv => false,
        };
        json!({
            "name": "capture-service",
            "provider": self.provider.as_str(),
            "managed": self.provider.is_managed(),
            "running": running,
            "port": self.port,
            "origin": self.origin,
            "processAvailable": process_available,
            "executable": exe,
            "fallback": "simulated-eight-camera",
            "lifecycle": {
                "phase": lifecycle.phase,
                "desiredRunning": lifecycle.desired_running,
                "autostart": lifecycle.autostart,
                "pid": lifecycle.pid,
                "startedAt": lifecycle.started_at.map(|value| value.to_string()),
                "readyAt": lifecycle.ready_at.map(|value| value.to_string()),
                "lastExitAt": lifecycle.last_exit_at.map(|value| value.to_string()),
                "lastExitCode": lifecycle.last_exit_code,
                "lastError": lifecycle.last_error,
                "restartCount": lifecycle.restart_count,
                "consecutiveFailures": lifecycle.consecutive_failures,
                "unhealthyConfirmations": lifecycle.unhealthy_confirmations,
                "restartBudget": lifecycle.restart_budget,
                "restartBudgetExhausted": lifecycle.consecutive_failures >= lifecycle.restart_budget,
                "nextRestartAt": lifecycle.next_restart_at.map(|value| value.to_string())
            }
        })
        .to_string()
    }

    fn simulated_proxy(&self, method: &str, path_with_query: &str, body: &str) -> Option<Vec<u8>> {
        let path = path_with_query.split('?').next().unwrap_or(path_with_query);
        match (method, path) {
            ("GET", "/api/steel/status") => {
                let capture_mode = self
                    .simulated_capture_mode
                    .lock()
                    .map(|mode| mode.clone())
                    .unwrap_or_else(|_| "continuous".to_string());
                let time_trigger_freq = self
                    .simulated_continuous_line_rate
                    .lock()
                    .map(|rate| *rate)
                    .unwrap_or(300.0);
                Some(
                    json!({
                        "code": 0,
                        "provider": "simulated",
                        "phase": "idle",
                        "present": false,
                        "saveEnabled": false,
                        "captureMode": capture_mode,
                        "automaticCaptureEnabled": capture_mode == "continuous",
                        "productionCaptureRunning": false,
                        "connectedCameras": CAPTURE_CAMERA_IPS.len(),
                        "continuousSettings": {
                            "timeTriggerFreq": time_trigger_freq,
                            "applyToDevice": false,
                            "runtimeOnly": true,
                            "restartContinuous": true
                        },
                        "storageRoot": "simulated",
                        "updatedAt": current_time_string()
                    })
                    .to_string()
                    .into_bytes(),
                )
            }
            ("GET", "/api/capture/continuous-settings") => {
                let capture_mode = self
                    .simulated_capture_mode
                    .lock()
                    .map(|mode| mode.clone())
                    .unwrap_or_else(|_| "continuous".to_string());
                let time_trigger_freq = self
                    .simulated_continuous_line_rate
                    .lock()
                    .map(|rate| *rate)
                    .unwrap_or(300.0);
                Some(
                    json!({
                        "code": 0,
                        "provider": "simulated",
                        "supported": true,
                        "timeTriggerFreq": time_trigger_freq,
                        "lineTriggerFrequency": time_trigger_freq,
                        "connectedCameras": CAPTURE_CAMERA_IPS.len(),
                        "configuredCameras": CAPTURE_CAMERA_IPS.len(),
                        "captureMode": capture_mode,
                        "requiresApplyToDevice": true,
                        "runtimeOnly": true
                    })
                    .to_string()
                    .into_bytes(),
                )
            }
            ("POST", "/api/steel/capture-mode") => {
                let payload =
                    serde_json::from_str::<Value>(body.trim()).unwrap_or_else(|_| json!({}));
                let requested =
                    simulated_provider_string_field(&payload, &["captureMode", "capture_mode"]);
                let Some(capture_mode) = normalize_capture_output_mode(&requested) else {
                    return Some(
                        json!({
                            "code": 400,
                            "error": "captureMode must be continuous, on-demand, or disabled"
                        })
                        .to_string()
                        .into_bytes(),
                    );
                };
                if let Ok(mut current) = self.simulated_capture_mode.lock() {
                    *current = capture_mode.to_string();
                }
                Some(
                    json!({
                        "code": 0,
                        "provider": "simulated",
                        "captureMode": capture_mode,
                        "automaticCaptureEnabled": capture_mode == "continuous",
                        "productionCaptureRunning": false,
                        "updatedAt": current_time_string()
                    })
                    .to_string()
                    .into_bytes(),
                )
            }
            ("POST", "/api/capture/continuous-settings") => {
                let payload =
                    serde_json::from_str::<Value>(body.trim()).unwrap_or_else(|_| json!({}));
                let Some(time_trigger_freq) = payload
                    .get("timeTriggerFreq")
                    .or_else(|| payload.get("time_trigger_freq"))
                    .and_then(Value::as_f64)
                    .filter(|value| value.is_finite() && *value >= 0.1 && *value <= 100_000.0)
                else {
                    return Some(
                        json!({
                            "code": 400,
                            "error": "timeTriggerFreq must be between 0.1 and 100000"
                        })
                        .to_string()
                        .into_bytes(),
                    );
                };
                let apply_to_device = payload
                    .get("applyToDevice")
                    .or_else(|| payload.get("apply_to_device"))
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                let restart_continuous = payload
                    .get("restartContinuous")
                    .or_else(|| payload.get("restart_continuous"))
                    .and_then(Value::as_bool)
                    .unwrap_or(true);
                if apply_to_device {
                    if let Ok(mut current) = self.simulated_continuous_line_rate.lock() {
                        *current = time_trigger_freq;
                    }
                }
                let current_time_trigger_freq = self
                    .simulated_continuous_line_rate
                    .lock()
                    .map(|rate| *rate)
                    .unwrap_or(300.0);
                Some(
                    json!({
                        "code": 0,
                        "provider": "simulated",
                        "timeTriggerFreq": current_time_trigger_freq,
                        "requestedTimeTriggerFreq": time_trigger_freq,
                        "applyToDevice": apply_to_device,
                        "runtimeOnly": true,
                        "restartContinuous": restart_continuous,
                        "applied": if apply_to_device { CAPTURE_CAMERA_IPS.len() } else { 0 },
                        "failed": 0,
                        "updatedAt": current_time_string()
                    })
                    .to_string()
                    .into_bytes(),
                )
            }
            ("POST", "/api/steel/event") => {
                let payload =
                    serde_json::from_str::<Value>(body.trim()).unwrap_or_else(|_| json!({}));
                let requested_capture_mode =
                    simulated_provider_string_field(&payload, &["captureMode", "capture_mode"]);
                if !requested_capture_mode.is_empty() {
                    let Some(capture_mode) = normalize_capture_output_mode(&requested_capture_mode)
                    else {
                        return Some(
                            json!({
                                "code": 400,
                                "error": "captureMode must be continuous, on-demand, or disabled"
                            })
                            .to_string()
                            .into_bytes(),
                        );
                    };
                    if let Ok(mut current) = self.simulated_capture_mode.lock() {
                        *current = capture_mode.to_string();
                    }
                }
                let capture_mode = self
                    .simulated_capture_mode
                    .lock()
                    .map(|mode| mode.clone())
                    .unwrap_or_else(|_| "continuous".to_string());
                let material_id = {
                    let id = simulated_provider_string_field(
                        &payload,
                        &["id", "materialId", "steelId", "steelNo"],
                    );
                    if id.trim().is_empty() {
                        "simulated-material".to_string()
                    } else {
                        id
                    }
                };
                let session_id = simulated_provider_string_field(&payload, &["sessionId"]);
                let command = simulated_provider_string_field(&payload, &["cmd", "command"])
                    .if_empty("steelIn");
                let value = payload.get("value").and_then(Value::as_i64).unwrap_or(0);
                let save_enabled = payload
                    .get("saveEnabled")
                    .and_then(Value::as_bool)
                    .unwrap_or(value != 0 && command != "rcvSteelInfo");
                let automatic_capture = capture_mode == "continuous"
                    && payload
                        .get("autoCapture")
                        .and_then(Value::as_bool)
                        .unwrap_or(true);
                let phase = if command == "rcvSteelInfo" {
                    "info-ready"
                } else if value == 0 {
                    "steel-out"
                } else if save_enabled && automatic_capture {
                    "steel-in-saving"
                } else {
                    "steel-in-waiting-images"
                };
                Some(
                    json!({
                        "code": 0,
                        "provider": "simulated",
                        "cmd": command,
                        "value": value,
                        "id": material_id,
                        "materialId": material_id,
                        "steelId": material_id,
                        "sessionId": session_id,
                        "inspectionId": simulated_provider_string_field(&payload, &["inspectionId"]),
                        "phase": phase,
                        "present": value != 0 && command != "rcvSteelInfo",
                        "saveEnabled": save_enabled,
                        "captureMode": capture_mode,
                        "automaticCaptureEnabled": capture_mode == "continuous",
                        "productionCaptureRunning": automatic_capture
                            && value != 0
                            && command != "rcvSteelInfo",
                        "saveSdkDerived": false,
                        "discardBlackFrames": payload
                            .get("discardBlackFrames")
                            .and_then(Value::as_bool)
                            .unwrap_or(true),
                        "connectedCameras": CAPTURE_CAMERA_IPS.len(),
                        "updatedAt": current_time_string()
                    })
                    .to_string()
                    .into_bytes(),
                )
            }
            ("POST", "/api/capture/continuous-test") => {
                let payload =
                    serde_json::from_str::<Value>(body.trim()).unwrap_or_else(|_| json!({}));
                let material_id =
                    simulated_provider_string_field(&payload, &["materialId", "steelId", "id"])
                        .if_empty("simulated-material");
                let session_id = simulated_provider_string_field(&payload, &["sessionId"]);
                let expected_cameras = value_i32(
                    &payload,
                    &["expectedCameras", "expected_cameras"],
                    CAPTURE_CAMERA_IPS.len() as i32,
                )
                .clamp(1, CAPTURE_CAMERA_IPS.len() as i32)
                    as usize;
                let rounds = value_i32(&payload, &["rounds"], 1).clamp(1, 100) as usize;
                let lines = value_i32(&payload, &["lines", "triggerLines"], 1000).max(1);
                let width = value_i32(&payload, &["width"], 3200).max(0);
                let save_sdk_derived = value_bool(&payload, &["saveSdkDerived"], false);
                let started_at = current_time_string();
                let output_dir = format!("simulated://{material_id}");
                let mut results = Vec::new();

                for round in 1..=rounds {
                    for (index, ip) in CAPTURE_CAMERA_IPS.iter().take(expected_cameras).enumerate()
                    {
                        let camera_id = format!("camera{}", index + 1);
                        let shot = ((round - 1) * expected_cameras) + index + 1;
                        let base = format!(
                            "{}/{}/round-{round:03}-shot-{shot:04}",
                            output_dir, camera_id
                        );
                        results.push(json!({
                            "code": 0,
                            "errorName": "CORRECT",
                            "operatorHint": "simulated",
                            "round": round,
                            "parallelIndex": index,
                            "attempt": shot,
                            "ip": ip,
                            "cameraId": camera_id,
                            "completeFrame": true,
                            "depthExists": true,
                            "intensityExists": true,
                            "metadataExists": true,
                            "sdkExists": false,
                            "sdkDepthExists": false,
                            "sdkIntensityExists": false,
                            "width": width,
                            "lines": lines,
                            "fid": shot,
                            "lostLines": 0,
                            "triggerMinInterval": 0,
                            "triggerMaxInterval": 0,
                            "depthOutput": format!("{base}_depthMap.png"),
                            "intensityOutput": format!("{base}_intensity.png"),
                            "metadataOutput": format!("{base}_metadata.json"),
                            "sdkOutput": if save_sdk_derived {
                                format!("{base}_sdk.png")
                            } else {
                                String::new()
                            },
                            "sdkDepthOutput": "",
                            "sdkIntensityOutput": "",
                        }));
                    }
                }

                let attempts = results.len();
                Some(
                    json!({
                        "schema": "steel.capture.continuous-test.summary.v1",
                        "generatedAt": current_time_string(),
                        "startedAt": started_at,
                        "finishedAt": current_time_string(),
                        "code": 0,
                        "errorName": "CORRECT",
                        "operatorHint": "simulated",
                        "provider": "simulated",
                        "materialId": material_id.clone(),
                        "sessionId": session_id.clone(),
                        "attempts": attempts,
                        "successes": attempts,
                        "failures": 0,
                        "completeFrames": attempts,
                        "metadataFrames": attempts,
                        "discardedFrames": 0,
                        "blackFrames": 0,
                        "rounds": rounds,
                        "retries": 0,
                        "cameraCount": expected_cameras,
                        "expectedCameras": expected_cameras,
                        "expectedMet": true,
                        "connectFirst": false,
                        "parallel": true,
                        "saveSdkDerived": save_sdk_derived,
                        "workerCount": expected_cameras,
                        "roundIntervalMs": value_i32(&payload, &["intervalMs"], 0),
                        "elapsedMs": 1,
                        "syncMode": "simulated-round-start-condition-variable",
                        "storageRoot": "simulated",
                        "outputDir": output_dir,
                        "summaryOutput": format!("simulated://{material_id}/summary.json"),
                        "summaryExists": true,
                        "results": results
                    })
                    .to_string()
                    .into_bytes(),
                )
            }
            _ => None,
        }
    }

    fn proxy(&self, method: &str, path_with_query: &str, body: &str) -> Option<Vec<u8>> {
        self.proxy_with_read_timeout(method, path_with_query, body, Duration::from_secs(8))
    }

    fn proxy_with_read_timeout(
        &self,
        method: &str,
        path_with_query: &str,
        body: &str,
        read_timeout: Duration,
    ) -> Option<Vec<u8>> {
        self.proxy_response_with_read_timeout(method, path_with_query, body, read_timeout)
            .filter(|response| (200..300).contains(&response.status_code))
            .map(|response| response.body)
    }

    fn proxy_response(
        &self,
        method: &str,
        path_with_query: &str,
        body: &str,
    ) -> Option<CaptureProxyResponse> {
        self.proxy_response_with_read_timeout(method, path_with_query, body, Duration::from_secs(8))
    }

    fn proxy_response_with_read_timeout(
        &self,
        method: &str,
        path_with_query: &str,
        body: &str,
        read_timeout: Duration,
    ) -> Option<CaptureProxyResponse> {
        if self.provider == CaptureProvider::Simulated {
            return self
                .simulated_proxy(method, path_with_query, body)
                .map(|body| CaptureProxyResponse {
                    status_code: 200,
                    content_type: "application/json; charset=utf-8".to_string(),
                    body,
                });
        }
        if !self.provider.uses_local_api() {
            return None;
        }
        // The request itself is the availability check. A separate TCP probe
        // here doubles every preview connection and can overflow the provider
        // accept queue when six camera images refresh together. Lifecycle
        // health remains updated by the dedicated supervisor thread.
        self.request_response_with_read_timeout(method, path_with_query, body, read_timeout)
    }

    fn probe_response(
        &self,
        path_with_query: &str,
        read_timeout: Duration,
    ) -> Option<CaptureProxyResponse> {
        if self.provider == CaptureProvider::Simulated || !self.provider.uses_local_api() {
            return None;
        }
        self.request_response_with_read_timeout("GET", path_with_query, "", read_timeout)
    }

    fn request_response_with_read_timeout(
        &self,
        method: &str,
        path_with_query: &str,
        body: &str,
        read_timeout: Duration,
    ) -> Option<CaptureProxyResponse> {
        let mut addresses = (self.host.as_str(), self.port).to_socket_addrs().ok()?;
        let mut stream = addresses.find_map(|address| {
            TcpStream::connect_timeout(&address, Duration::from_millis(1500)).ok()
        })?;
        let _ = stream.set_read_timeout(Some(read_timeout));
        let _ = stream.set_write_timeout(Some(Duration::from_secs(8)));
        let request = format!(
            "{method} {path_with_query} HTTP/1.1\r\nHost: {}:{}\r\nConnection: close\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
            self.host,
            self.port,
            body.as_bytes().len(),
            body
        );
        stream.write_all(request.as_bytes()).ok()?;
        let mut response = Vec::new();
        stream.read_to_end(&mut response).ok()?;
        parse_capture_http_response(response)
    }
}

fn parse_capture_http_response(response: Vec<u8>) -> Option<CaptureProxyResponse> {
    let marker = b"\r\n\r\n";
    let header_end = response
        .windows(marker.len())
        .position(|window| window == marker)?;
    let body_start = header_end + marker.len();
    let header_text = String::from_utf8_lossy(&response[..header_end]);
    let status_code = header_text
        .lines()
        .next()
        .and_then(|line| line.split_whitespace().nth(1))
        .and_then(|code| code.parse::<u16>().ok())?;
    let content_type = header_text
        .lines()
        .skip(1)
        .find_map(|line| {
            let (name, value) = line.split_once(':')?;
            name.trim()
                .eq_ignore_ascii_case("content-type")
                .then(|| value.trim().to_string())
        })
        .unwrap_or_else(|| "application/json; charset=utf-8".to_string());
    Some(CaptureProxyResponse {
        status_code,
        content_type,
        body: response[body_start..].to_vec(),
    })
}

fn plate_json(plate: &Plate) -> String {
    format!(
        "{{\"plateNo\":\"{}\",\"widthMm\":{},\"lengthMm\":{},\"thicknessMm\":{},\"steelGrade\":\"{}\",\"detectedAt\":\"{}\"}}",
        json_escape(&plate.plate_no),
        plate.width_mm,
        plate.length_mm,
        plate.thickness_mm,
        json_escape(&plate.steel_grade),
        json_escape(&plate.detected_at)
    )
}

fn defect_json(defect: &Defect) -> String {
    format!(
        "{{\"id\":\"{}\",\"plateNo\":\"{}\",\"typeId\":\"{}\",\"typeLabel\":\"{}\",\"surface\":\"{}\",\"severity\":\"{}\",\"distanceHeadMm\":{},\"operatorSideMm\":{},\"driveSideMm\":{},\"widthMm\":{:.3},\"heightMm\":{:.3},\"depthMm\":{:.3},\"xRatio\":{:.5},\"yOffsetMm\":{:.5},\"previewX\":{},\"previewY\":{},\"previewImageUrl\":\"\"}}",
        json_escape(&defect.id),
        json_escape(&defect.plate_no),
        json_escape(&defect.type_id),
        json_escape(&defect.type_label),
        defect.surface,
        json_escape(&defect.severity),
        defect.distance_head_mm,
        defect.operator_side_mm,
        defect.drive_side_mm,
        defect.width_mm,
        defect.height_mm,
        defect.depth_mm,
        defect.x_ratio,
        defect.y_offset_mm,
        defect.preview_x,
        defect.preview_y
    )
}

fn defects_json(defects: &[Defect]) -> String {
    format!(
        "[{}]",
        defects
            .iter()
            .map(defect_json)
            .collect::<Vec<_>>()
            .join(",")
    )
}

fn height_profile_json(values: &[f64]) -> String {
    format!(
        "[{}]",
        values
            .iter()
            .enumerate()
            .map(|(index, z)| format!("{{\"x\":{},\"z\":{:.5}}}", index, z))
            .collect::<Vec<_>>()
            .join(",")
    )
}

fn build_snapshot_json() -> String {
    let current_plate = plate_from_record(&RECORDS[0], 0);
    let current_defects = current_defects();
    let current_height = height_profile(-0.18, 36);
    let defect_types = DEFECT_TYPES
        .iter()
        .map(|item| {
            format!(
                "{{\"id\":\"{}\",\"label\":\"{}\",\"color\":\"{}\",\"shape\":\"{}\"}}",
                item.id,
                json_escape(item.label),
                item.color,
                item.shape
            )
        })
        .collect::<Vec<_>>()
        .join(",");
    let records = RECORDS
        .iter()
        .map(|record| {
            format!(
                "{{\"id\":\"{}\",\"time\":\"{}\",\"plateNo\":\"{}\",\"status\":\"{}\",\"defectCount\":{}}}",
                record.id, record.time, record.plate_no, record.status, record.defect_count
            )
        })
        .collect::<Vec<_>>()
        .join(",");
    let inspections = RECORDS
        .iter()
        .enumerate()
        .map(|(index, record)| {
            let plate = plate_from_record(record, index);
            let defects = defects_for_record(record, &plate, index);
            let profile = if index == 0 {
                current_height.clone()
            } else {
                height_profile(
                    defects.first().map(|item| item.depth_mm).unwrap_or(-0.02),
                    28 + ((index * 7) % 22) as i32,
                )
            };
            format!(
                "{{\"plate\":{},\"defects\":{},\"heightProfile\":{}}}",
                plate_json(&plate),
                defects_json(&defects),
                height_profile_json(&profile)
            )
        })
        .collect::<Vec<_>>()
        .join(",");

    format!(
        "{{\"currentPlate\":{},\"defectTypes\":[{}],\"defects\":{},\"records\":[{}],\"status\":{},\"summary\":{},\"heightProfile\":{},\"inspections\":[{}]}}",
        plate_json(&current_plate),
        defect_types,
        defects_json(&current_defects),
        records,
        "{\"receiverPorts\":[{\"index\":1,\"ok\":true},{\"index\":2,\"ok\":true},{\"index\":3,\"ok\":false},{\"index\":4,\"ok\":true},{\"index\":5,\"ok\":true},{\"index\":6,\"ok\":true},{\"index\":7,\"ok\":true},{\"index\":8,\"ok\":true}],\"cameraPorts\":[{\"index\":1,\"ok\":true},{\"index\":2,\"ok\":true},{\"index\":3,\"ok\":false},{\"index\":4,\"ok\":true},{\"index\":5,\"ok\":true},{\"index\":6,\"ok\":true},{\"index\":7,\"ok\":true},{\"index\":8,\"ok\":true}],\"encoder\":\"sync\",\"plc\":\"normal\",\"l2\":\"normal\",\"alarmCount\":1}",
        "{\"total\":12,\"bySeverity\":{\"severe\":4,\"review\":3,\"minor\":5},\"bySurface\":{\"top\":5,\"bottom\":7}}",
        height_profile_json(&current_height),
        inspections
    )
}

