fn production_device_status_value(state: &ServiceState) -> Value {
    let statuses = state
        .capture
        .proxy("GET", "/api/camera/statuses", "")
        .and_then(|body| serde_json::from_slice::<Value>(&body).ok());
    let connected = statuses
        .as_ref()
        .and_then(|value| value.get("statuses"))
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .map(|item| {
                    item.get("connected")
                        .and_then(Value::as_bool)
                        .unwrap_or(false)
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let camera_ports = (0..CAPTURE_CAMERA_IPS.len())
        .map(|index| json!({ "index": index + 1, "ok": connected.get(index).copied().unwrap_or(false) }))
        .collect::<Vec<_>>();
    let alarm_count = state
        .runtime
        .block_on(db::production_alarm_counts(&state.database.connection))
        .map(|counts| counts.active.saturating_add(counts.acknowledged))
        .unwrap_or(0);
    json!({
        "receiverPorts": (0..8).map(|index| json!({ "index": index + 1, "ok": true })).collect::<Vec<_>>(),
        "cameraPorts": camera_ports,
        "encoder": "sync",
        "plc": "normal",
        "l2": "normal",
        "alarmCount": alarm_count
    })
}

fn selected_bkv_inspection_for_view(
    state: &ServiceState,
) -> Result<Option<db::entities::production_inspection::Model>, production_tasks::BkvRejection> {
    match production_tasks::configured_bkv_root() {
        Ok(root) => {
            let replay =
                state
                    .runtime
                    .block_on(production_tasks::load_bkv_replay_runtime_with_deadline(
                        &state.database.connection,
                        &root,
                        Some(Instant::now() + Duration::from_millis(1_500)),
                    ))?;
            state
                .runtime
                .block_on(production_tasks::selected_bkv_inspection_exact(
                    &state.database.connection,
                    &replay.deterministic_inspections,
                ))
        }
        Err(error) => {
            #[cfg(test)]
            {
                let _ = error;
                state
                    .runtime
                    .block_on(production_tasks::selected_bkv_inspection_unverified_test(
                        &state.database.connection,
                    ))
            }
            #[cfg(not(test))]
            {
                Err(error)
            }
        }
    }
}

struct BkvSnapshotSelection {
    inspection: Option<db::entities::production_inspection::Model>,
    batch_id: String,
    content_id: String,
    active_snapshot: Value,
    replay_snapshot: Value,
    replay_identity: BkvReplayIdentity,
    batch_snapshot: Option<Value>,
    artifacts: Vec<production_tasks::BkvServingArtifact>,
    depth_decode: HashMap<String, Value>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct BkvReplayIdentity {
    batch_id: String,
    content_id: String,
    index: usize,
    status: String,
    version: i64,
    selected_legacy_seq_no: Option<i64>,
    selected_inspection_id: Option<String>,
}

fn strict_bkv_replay_identity(value: &Value) -> Result<BkvReplayIdentity, String> {
    let object = value
        .as_object()
        .ok_or_else(|| "bkv_replay_state_invalid".to_string())?;
    let batch_id = object
        .get("batchId")
        .and_then(Value::as_str)
        .filter(|value| {
            !value.is_empty()
                && value.len() <= 117
                && !matches!(*value, "." | "..")
                && value
                    .bytes()
                    .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.'))
        })
        .ok_or_else(|| "bkv_replay_state_invalid".to_string())?
        .to_string();
    let content_id = object
        .get("contentId")
        .and_then(Value::as_str)
        .filter(|value| {
            value.len() == 64
                && value
                    .bytes()
                    .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
        })
        .ok_or_else(|| "bkv_replay_state_invalid".to_string())?
        .to_string();
    let index = object
        .get("index")
        .and_then(Value::as_u64)
        .and_then(|value| usize::try_from(value).ok())
        .filter(|value| *value <= 11)
        .ok_or_else(|| "bkv_replay_state_invalid".to_string())?;
    let status = object
        .get("status")
        .and_then(Value::as_str)
        .ok_or_else(|| "bkv_replay_state_invalid".to_string())?;
    let expected_status = if index == 0 {
        "ready"
    } else if index == 11 {
        "completed"
    } else {
        "replaying"
    };
    let version = object
        .get("version")
        .and_then(Value::as_i64)
        .filter(|value| *value >= index as i64)
        .ok_or_else(|| "bkv_replay_state_invalid".to_string())?;
    let selected_legacy_seq_no = object.get("selectedLegacySeqNo").and_then(Value::as_i64);
    let selected_inspection_id = object
        .get("selectedInspectionId")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    if status != expected_status
        || (index == 0 && (selected_legacy_seq_no.is_some() || selected_inspection_id.is_some()))
        || (index > 0
            && (selected_legacy_seq_no != Some(1_893_699 + index as i64)
                || selected_inspection_id.is_none()))
        || object
            .get("selectedLegacySeqNo")
            .is_some_and(|value| !value.is_null() && value.as_i64().is_none())
        || object
            .get("selectedInspectionId")
            .is_some_and(|value| !value.is_null() && value.as_str().is_none())
    {
        return Err("bkv_replay_state_invalid".to_string());
    }
    Ok(BkvReplayIdentity {
        batch_id,
        content_id,
        index,
        status: status.to_string(),
        version,
        selected_legacy_seq_no,
        selected_inspection_id,
    })
}

fn bkv_active_snapshot_matches(value: &Value, batch_id: &str, content_id: &str) -> bool {
    value.as_object().is_some_and(|object| {
        object.len() == 2
            && object.get("batchId").and_then(Value::as_str) == Some(batch_id)
            && object.get("contentId").and_then(Value::as_str) == Some(content_id)
    })
}

fn selected_bkv_snapshot_selection(
    state: &ServiceState,
) -> Result<Option<BkvSnapshotSelection>, String> {
    match production_tasks::configured_bkv_root() {
        Ok(root) => {
            let replay = state
                .runtime
                .block_on(production_tasks::load_bkv_replay_runtime_with_deadline(
                    &state.database.connection,
                    &root,
                    Some(Instant::now() + Duration::from_millis(1_500)),
                ))
                .map_err(|error| error.code.to_string())?;
            let replay_identity = strict_bkv_replay_identity(&replay.replay_snapshot)?;
            if replay_identity.batch_id != replay.batch_id
                || replay_identity.content_id != replay.content_id
                || replay_identity.index != replay.replay_index
                || replay_identity.status != replay.replay_status
                || replay_identity.version != replay.replay_version
            {
                return Err("bkv_replay_state_invalid".to_string());
            }
            let active_snapshot = state
                .runtime
                .block_on(db::get_config(
                    &state.database.connection,
                    "bkv.active-batch",
                ))
                .map_err(|_| "bkv_status_unavailable".to_string())?
                .and_then(|value| serde_json::from_str::<Value>(&value.value).ok())
                .ok_or_else(|| "bkv_active_batch_missing".to_string())?;
            if !bkv_active_snapshot_matches(&active_snapshot, &replay.batch_id, &replay.content_id)
            {
                return Err("bkv_replay_changed".to_string());
            }
            let (batch_snapshot, depth_decode) = load_bkv_depth_decode_evidence(
                state,
                &root,
                &replay.batch_id,
                &replay.content_id,
                &replay.artifacts,
            )
            .ok_or_else(|| "bkv_manifest_invalid".to_string())?;
            let selected = state
                .runtime
                .block_on(production_tasks::selected_bkv_inspection_exact(
                    &state.database.connection,
                    &replay.deterministic_inspections,
                ))
                .map_err(|error| error.code.to_string())?;
            if selected.as_ref().map(|value| value.id.as_str())
                != replay_identity.selected_inspection_id.as_deref()
            {
                return Err("bkv_replay_changed".to_string());
            }
            Ok(Some(BkvSnapshotSelection {
                inspection: selected,
                batch_id: replay.batch_id,
                content_id: replay.content_id,
                active_snapshot,
                replay_snapshot: replay.replay_snapshot,
                replay_identity,
                batch_snapshot: Some(batch_snapshot),
                artifacts: replay.artifacts,
                depth_decode,
            }))
        }
        Err(error) => {
            #[cfg(test)]
            {
                let _ = error;
                let selected = state
                    .runtime
                    .block_on(production_tasks::selected_bkv_inspection_unverified_test(
                        &state.database.connection,
                    ))
                    .map_err(|error| error.code.to_string())?;
                let active_snapshot = state
                    .runtime
                    .block_on(db::get_config(
                        &state.database.connection,
                        "bkv.active-batch",
                    ))
                    .map_err(|_| "bkv_status_unavailable".to_string())?
                    .and_then(|value| serde_json::from_str::<Value>(&value.value).ok())
                    .ok_or_else(|| "bkv_active_batch_missing".to_string())?;
                let batch_id = active_snapshot
                    .get("batchId")
                    .and_then(Value::as_str)
                    .ok_or_else(|| "bkv_replay_state_invalid".to_string())?
                    .to_string();
                let content_id = active_snapshot
                    .get("contentId")
                    .and_then(Value::as_str)
                    .ok_or_else(|| "bkv_replay_state_invalid".to_string())?
                    .to_string();
                let replay_snapshot = state
                    .runtime
                    .block_on(db::get_config(
                        &state.database.connection,
                        &format!("bkv.replay.{batch_id}"),
                    ))
                    .map_err(|_| "bkv_status_unavailable".to_string())?
                    .and_then(|value| serde_json::from_str::<Value>(&value.value).ok())
                    .ok_or_else(|| "bkv_replay_state_missing".to_string())?;
                let replay_identity = strict_bkv_replay_identity(&replay_snapshot)?;
                if !bkv_active_snapshot_matches(&active_snapshot, &batch_id, &content_id)
                    || replay_identity.batch_id != batch_id
                    || replay_identity.content_id != content_id
                    || selected.as_ref().map(|value| value.id.as_str())
                        != replay_identity.selected_inspection_id.as_deref()
                {
                    return Err("bkv_replay_changed".to_string());
                }
                let batch_snapshot = state
                    .runtime
                    .block_on(db::get_config(
                        &state.database.connection,
                        &format!("bkv.batch.{batch_id}"),
                    ))
                    .ok()
                    .flatten()
                    .and_then(|value| serde_json::from_str::<Value>(&value.value).ok());
                Ok(Some(BkvSnapshotSelection {
                    inspection: selected,
                    batch_id,
                    content_id,
                    active_snapshot,
                    replay_snapshot,
                    replay_identity,
                    batch_snapshot,
                    artifacts: Vec::new(),
                    depth_decode: HashMap::new(),
                }))
            }
            #[cfg(not(test))]
            {
                Err(error.code.to_string())
            }
        }
    }
}

fn same_bkv_inspection_model(
    left: &db::entities::production_inspection::Model,
    right: &db::entities::production_inspection::Model,
) -> bool {
    left.id == right.id
        && left.material_id == right.material_id
        && left.session_id == right.session_id
        && left.status == right.status
        && left.storage_root == right.storage_root
        && left.summary_path == right.summary_path
        && left.started_at == right.started_at
        && left.finished_at == right.finished_at
        && left.capture_count == right.capture_count
        && left.defect_count == right.defect_count
        && left.raw_payload == right.raw_payload
}

fn validate_bkv_snapshot_selection_fence(
    state: &ServiceState,
    selection: &BkvSnapshotSelection,
) -> Result<(), String> {
    let active = state
        .runtime
        .block_on(db::get_config(
            &state.database.connection,
            "bkv.active-batch",
        ))
        .map_err(|_| "bkv_status_unavailable".to_string())?
        .and_then(|value| serde_json::from_str::<Value>(&value.value).ok())
        .ok_or_else(|| "bkv_replay_changed".to_string())?;
    if active != selection.active_snapshot
        || !bkv_active_snapshot_matches(&active, &selection.batch_id, &selection.content_id)
    {
        return Err("bkv_replay_changed".to_string());
    }
    let replay = state
        .runtime
        .block_on(db::get_config(
            &state.database.connection,
            &format!("bkv.replay.{}", selection.batch_id),
        ))
        .map_err(|_| "bkv_status_unavailable".to_string())?
        .and_then(|value| serde_json::from_str::<Value>(&value.value).ok())
        .ok_or_else(|| "bkv_replay_changed".to_string())?;
    if replay != selection.replay_snapshot
        || strict_bkv_replay_identity(&replay).ok().as_ref() != Some(&selection.replay_identity)
    {
        return Err("bkv_replay_changed".to_string());
    }
    if let Some(expected_batch) = selection.batch_snapshot.as_ref() {
        let batch = state
            .runtime
            .block_on(db::get_config(
                &state.database.connection,
                &format!("bkv.batch.{}", selection.batch_id),
            ))
            .map_err(|_| "bkv_status_unavailable".to_string())?
            .and_then(|value| serde_json::from_str::<Value>(&value.value).ok())
            .ok_or_else(|| "bkv_replay_changed".to_string())?;
        if &batch != expected_batch
            || batch.get("batchId").and_then(Value::as_str) != Some(selection.batch_id.as_str())
            || batch.get("contentId").and_then(Value::as_str) != Some(selection.content_id.as_str())
            || !matches!(
                batch.get("status").and_then(Value::as_str),
                Some("ready" | "partial")
            )
        {
            return Err("bkv_replay_changed".to_string());
        }
    }
    match (
        &selection.inspection,
        &selection.replay_identity.selected_inspection_id,
    ) {
        (None, None) => Ok(()),
        (Some(expected), Some(id)) if expected.id == *id => {
            let current = state
                .runtime
                .block_on(db::find_production_inspection(
                    &state.database.connection,
                    id,
                ))
                .map_err(|_| "bkv_status_unavailable".to_string())?
                .ok_or_else(|| "bkv_replay_changed".to_string())?;
            if same_bkv_inspection_model(expected, &current) {
                Ok(())
            } else {
                Err("bkv_replay_changed".to_string())
            }
        }
        _ => Err("bkv_replay_changed".to_string()),
    }
}

fn build_production_snapshot_json(state: &ServiceState) -> Result<Option<String>, String> {
    let selected_bkv_snapshot = if state.capture.provider == CaptureProvider::Bkv {
        selected_bkv_snapshot_selection(state)?
    } else {
        None
    };
    // Runtime/index verification may hash many artifacts. Perform that bounded verification
    // before entering the short command fence; snapshot assembly below uses only verified
    // serving-index metadata and database rows.
    let _bkv_command_guard = if state.capture.provider == CaptureProvider::Bkv {
        Some(
            state
                .production_command_lock
                .lock()
                .map_err(|_| "production_command_lock_poisoned".to_string())?,
        )
    } else {
        None
    };
    if let Some(selection) = selected_bkv_snapshot.as_ref() {
        validate_bkv_snapshot_selection_fence(state, selection)?;
    }
    if state.capture.provider == CaptureProvider::Bkv
        && selected_bkv_snapshot
            .as_ref()
            .and_then(|selection| selection.inspection.as_ref())
            .is_none()
    {
        return Ok(Some(
            json!({
                "currentPlate": {
                    "plateNo":"暂无BKV回放记录","widthMm":0,"lengthMm":0,
                    "thicknessMm":0,"steelGrade":"-","detectedAt":""
                },
                "defectTypes":production_defect_types_value(),
                "defects":[],"records":[],
                "status":{
                    "receiverPorts":[],
                    "cameraPorts":(1..=6).map(|index| json!({
                        "index":index,"ok":false,"offline":true,"source":"bkv"
                    })).collect::<Vec<_>>(),
                    "encoder":"offline","plc":"offline","l2":"offline","alarmCount":0
                },
                "summary":summarize_defect_values(&[]),
                "heightProfile":[],"inspections":[],"captureImages":[],
                "source":"bkv-offline","provider":"bkv","sourceBadge":"BKV 离线回放",
                "offline":true,"bkvArtifacts":[]
            })
            .to_string(),
        ));
    }
    drop(_bkv_command_guard);
    let bkv_binding = selected_bkv_snapshot
        .as_ref()
        .and_then(|selection| selection.inspection.as_ref())
        .and_then(|inspection| serde_json::from_str::<Value>(&inspection.raw_payload).ok());
    let bkv_batch_id = selected_bkv_snapshot
        .as_ref()
        .map(|selection| selection.batch_id.clone());
    let bkv_expected_artifacts = selected_bkv_snapshot
        .as_ref()
        .map(|selection| selection.artifacts.clone())
        .unwrap_or_default();
    let bkv_depth_decode = selected_bkv_snapshot
        .as_ref()
        .map(|selection| selection.depth_decode.clone())
        .unwrap_or_default();
    let selected_bkv_inspection = selected_bkv_snapshot.and_then(|selection| selection.inspection);
    let inspections = if state.capture.provider == CaptureProvider::Bkv {
        vec![selected_bkv_inspection
            .expect("BKV selected inspection is guarded before snapshot assembly")]
    } else {
        state
            .runtime
            .block_on(db::list_recent_production_inspections(
                &state.database.connection,
                20,
            ))
            .map_err(|error| error.to_string())?
    };
    if inspections.is_empty() {
        return Ok(None);
    }

    let mut records = Vec::new();
    let mut plate_inspections = Vec::new();
    let mut current_plate = json!({
        "plateNo": "",
        "widthMm": 0,
        "lengthMm": 0,
        "thicknessMm": 0,
        "steelGrade": "实际生产",
        "detectedAt": ""
    });
    let mut current_defects = Vec::new();
    let mut current_capture_images = Vec::new();
    let mut current_bkv_artifacts = Vec::new();

    for (index, inspection) in inspections.iter().enumerate() {
        let session = state
            .runtime
            .block_on(db::find_material_session(
                &state.database.connection,
                &inspection.session_id,
            ))
            .map_err(|error| error.to_string())?;
        let files = if state.capture.provider == CaptureProvider::Bkv {
            state
                .runtime
                .block_on(db::capture_files_for_inspection(
                    &state.database.connection,
                    &inspection.id,
                ))
                .map_err(|error| error.to_string())?
        } else {
            state
                .runtime
                .block_on(db::recent_preview_capture_files_for_inspection(
                    &state.database.connection,
                    &inspection.id,
                    128,
                ))
                .map_err(|error| error.to_string())?
        };
        let production_defects = state
            .runtime
            .block_on(db::production_defects_for_inspection(
                &state.database.connection,
                &inspection.id,
            ))
            .map_err(|error| error.to_string())?;
        let plate = production_plate_value(inspection, session.as_ref());
        let defects = production_defects
            .iter()
            .map(|defect| production_defect_value(defect, inspection, &plate))
            .collect::<Vec<_>>();
        let (legacy_capture_images, bkv_artifacts) =
            if state.capture.provider == CaptureProvider::Bkv {
                let artifacts = files
                    .iter()
                    .map(|file| {
                        production_capture_image_value_for_bkv_artifacts(
                            &bkv_expected_artifacts,
                            &bkv_depth_decode,
                            bkv_batch_id.as_deref()?,
                            file,
                        )
                    })
                    .collect::<Option<Vec<_>>>()
                    .ok_or_else(|| "bkv_artifact_unavailable".to_string())?;
                (Vec::new(), artifacts)
            } else {
                let mut latest_by_component: HashMap<
                    (String, String),
                    &db::entities::capture_file::Model,
                > = HashMap::new();
                for file in &files {
                    let key = (file.camera_id.clone(), file.data_name.to_ascii_lowercase());
                    let replace = latest_by_component
                        .get(&key)
                        .is_none_or(|current| current.sequence_no < file.sequence_no);
                    if replace {
                        latest_by_component.insert(key, file);
                    }
                }
                let mut previews = latest_by_component.into_values().collect::<Vec<_>>();
                previews.sort_by(|left, right| {
                    left.camera_id
                        .cmp(&right.camera_id)
                        .then_with(|| left.data_name.cmp(&right.data_name))
                });
                (
                    previews
                        .into_iter()
                        .map(production_capture_image_value)
                        .collect(),
                    Vec::new(),
                )
            };
        let capture_summary_path = production_session_summary_path(
            &inspection.storage_root,
            &inspection.material_id,
            &inspection.session_id,
        )
        .map(|path| path.display().to_string())
        .unwrap_or_default();
        if index == 0 {
            current_plate = plate.clone();
            current_defects = defects.clone();
            current_capture_images = legacy_capture_images.clone();
            current_bkv_artifacts = bkv_artifacts.clone();
        }
        records.push(json!({
            "id": inspection.session_id,
            "time": production_time_label(&inspection.started_at, &inspection.material_id),
            "plateNo": inspection.material_id,
            "status": production_record_status(&inspection.status),
            "defectCount": defects.len()
        }));
        plate_inspections.push(json!({
            "plate": plate,
            "defects": defects,
            "heightProfile": [],
            "captureImages": legacy_capture_images,
            "bkvArtifacts": bkv_artifacts,
            "inspectionId": inspection.id,
            "summaryPath": inspection.summary_path,
            "captureSummaryPath": capture_summary_path,
            "source": if state.capture.provider == CaptureProvider::Bkv { "bkv" } else { "production" }
        }));
    }

    Ok(Some(
        json!({
            "currentPlate": current_plate,
            "defectTypes": production_defect_types_value(),
            "defects": current_defects,
            "records": records,
            "status": production_device_status_value(state),
            "summary": summarize_defect_values(&current_defects),
            "heightProfile": [],
            "inspections": plate_inspections,
            "captureImages": current_capture_images,
            "bkvArtifacts": current_bkv_artifacts,
            "source": if state.capture.provider == CaptureProvider::Bkv { "bkv" } else { "production-sqlite" },
            "provider": state.capture.provider.as_str(),
            "sourceBadge": if state.capture.provider == CaptureProvider::Bkv { "BKV 离线回放" } else { "" },
            "offline": state.capture.provider == CaptureProvider::Bkv,
            "batchId": bkv_binding.as_ref().and_then(|value| value.get("batchId")),
            "contentId": bkv_binding.as_ref().and_then(|value| value.get("contentId")),
            "legacySeqNo": bkv_binding.as_ref().and_then(|value| value.get("legacySeqNo"))
        })
        .to_string(),
    ))
}

fn build_database_snapshot_json(snapshot: db::DatabaseSnapshot) -> String {
    if snapshot.records.is_empty() && snapshot.plates.is_empty() {
        return json!({
            "currentPlate": {
                "plateNo": "暂无生产记录",
                "widthMm": 0,
                "lengthMm": 0,
                "thicknessMm": 0,
                "steelGrade": "-",
                "detectedAt": ""
            },
            "defectTypes": snapshot.defect_types.iter().map(|item| json!({
                "id": item.id,
                "label": item.label,
                "color": item.color,
                "shape": item.shape
            })).collect::<Vec<_>>(),
            "defects": [],
            "records": [],
            "status": {
                "receiverPorts": [],
                "cameraPorts": [],
                "encoder": "offline",
                "plc": "error",
                "l2": "error",
                "alarmCount": 0
            },
            "summary": {
                "total": 0,
                "bySeverity": { "severe": 0, "review": 0, "minor": 0 },
                "bySurface": { "top": 0, "bottom": 0 }
            },
            "heightProfile": [],
            "inspections": [],
            "source": "empty-production-sqlite"
        })
        .to_string();
    }
    let current_plate =
        snapshot
            .plates
            .first()
            .cloned()
            .unwrap_or(db::entities::steel_plate::Model {
                plate_no: "202606131900".to_string(),
                width_mm: 3500,
                length_mm: 12000,
                thickness_mm: 12,
                steel_grade: "Q355B".to_string(),
                detected_at: "2026-06-13 19:00".to_string(),
            });
    let current_defects = snapshot
        .defects
        .iter()
        .filter(|defect| defect.plate_no == current_plate.plate_no)
        .cloned()
        .collect::<Vec<_>>();
    let current_height = height_profile(-0.18, 36);
    let defect_types = snapshot
        .defect_types
        .iter()
        .map(|item| {
            format!(
                "{{\"id\":\"{}\",\"label\":\"{}\",\"color\":\"{}\",\"shape\":\"{}\"}}",
                json_escape(&item.id),
                json_escape(&item.label),
                json_escape(&item.color),
                json_escape(&item.shape)
            )
        })
        .collect::<Vec<_>>()
        .join(",");
    let records = snapshot
        .records
        .iter()
        .map(|record| {
            format!(
                "{{\"id\":\"{}\",\"time\":\"{}\",\"plateNo\":\"{}\",\"status\":\"{}\",\"defectCount\":{}}}",
                json_escape(&record.id),
                json_escape(&record.time),
                json_escape(&record.plate_no),
                json_escape(&record.status),
                record.defect_count
            )
        })
        .collect::<Vec<_>>()
        .join(",");
    let inspections = snapshot
        .records
        .iter()
        .filter_map(|record| {
            let plate = snapshot
                .plates
                .iter()
                .find(|plate| plate.plate_no == record.plate_no)?;
            let defects = snapshot
                .defects
                .iter()
                .filter(|defect| defect.plate_no == record.plate_no)
                .cloned()
                .collect::<Vec<_>>();
            let profile = height_profile(
                defects.first().map(|item| item.depth_mm).unwrap_or(-0.02),
                28,
            );
            Some(format!(
                "{{\"plate\":{},\"defects\":{},\"heightProfile\":{}}}",
                database_plate_json(plate),
                database_defects_json(&defects),
                height_profile_json(&profile)
            ))
        })
        .collect::<Vec<_>>()
        .join(",");

    format!(
        "{{\"currentPlate\":{},\"defectTypes\":[{}],\"defects\":{},\"records\":[{}],\"status\":{},\"summary\":{},\"heightProfile\":{},\"inspections\":[{}],\"source\":\"sqlite-seaorm\"}}",
        database_plate_json(&current_plate),
        defect_types,
        database_defects_json(&current_defects),
        records,
        "{\"receiverPorts\":[{\"index\":1,\"ok\":true},{\"index\":2,\"ok\":true},{\"index\":3,\"ok\":false},{\"index\":4,\"ok\":true},{\"index\":5,\"ok\":true},{\"index\":6,\"ok\":true},{\"index\":7,\"ok\":true},{\"index\":8,\"ok\":true}],\"cameraPorts\":[{\"index\":1,\"ok\":true},{\"index\":2,\"ok\":true},{\"index\":3,\"ok\":false},{\"index\":4,\"ok\":true},{\"index\":5,\"ok\":true},{\"index\":6,\"ok\":true},{\"index\":7,\"ok\":true},{\"index\":8,\"ok\":true}],\"encoder\":\"sync\",\"plc\":\"normal\",\"l2\":\"normal\",\"alarmCount\":1}",
        "{\"total\":12,\"bySeverity\":{\"severe\":4,\"review\":3,\"minor\":5},\"bySurface\":{\"top\":5,\"bottom\":7}}",
        height_profile_json(&current_height),
        inspections
    )
}

fn http_response_with_headers(
    status: &str,
    content_type: &str,
    body: &str,
    extra_headers: &[(&str, &str)],
) -> Vec<u8> {
    let extra_header_lines = extra_headers
        .iter()
        .map(|(name, value)| format!("{name}: {value}\r\n"))
        .collect::<String>();
    format!(
        "HTTP/1.1 {status}\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, POST, PATCH, PUT, DELETE, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type, Accept, Authorization, Idempotency-Key\r\n{extra_header_lines}Connection: close\r\n\r\n{}",
        body.as_bytes().len(),
        body
    )
    .into_bytes()
}

fn http_bytes_response_with_headers(
    status: &str,
    content_type: &str,
    body: &[u8],
    extra_headers: &[(&str, &str)],
) -> Vec<u8> {
    let extra_header_lines = extra_headers
        .iter()
        .map(|(name, value)| format!("{name}: {value}\r\n"))
        .collect::<String>();
    let mut response = format!(
        "HTTP/1.1 {status}\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, POST, PATCH, PUT, DELETE, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type, Accept, Authorization, Idempotency-Key\r\n{extra_header_lines}Connection: close\r\n\r\n",
        body.len()
    )
    .into_bytes();
    response.extend_from_slice(body);
    response
}

fn http_response(status: &str, content_type: &str, body: &str) -> Vec<u8> {
    http_response_with_headers(status, content_type, body, &[])
}

fn health_endpoint_for_route(method: &str, path: &str) -> Option<HealthEndpoint> {
    if method != "GET" {
        return None;
    }
    match path {
        "/api/health" => Some(HealthEndpoint::Compatibility),
        "/api/health/live" => Some(HealthEndpoint::Live),
        "/api/health/ready" => Some(HealthEndpoint::Ready),
        "/api/health/details" | "/api/health/ready/details" => Some(HealthEndpoint::Details),
        _ => None,
    }
}

fn health_latency_ms(started: Instant) -> u64 {
    started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum HealthHttpProbeError {
    InvalidOrigin,
    Unreachable,
    Timeout,
    InvalidResponse,
}

impl HealthHttpProbeError {
    fn as_str(self) -> &'static str {
        match self {
            Self::InvalidOrigin => "invalid_origin",
            Self::Unreachable => "unreachable",
            Self::Timeout => "timeout",
            Self::InvalidResponse => "invalid_response",
        }
    }
}

fn health_http_origin_endpoint(origin: &str) -> Result<(String, u16), HealthHttpProbeError> {
    let origin = origin.trim();
    let without_scheme = origin
        .strip_prefix("http://")
        .ok_or(HealthHttpProbeError::InvalidOrigin)?;
    let authority = without_scheme.split('/').next().unwrap_or_default().trim();
    if authority.is_empty() || authority.contains('@') {
        return Err(HealthHttpProbeError::InvalidOrigin);
    }
    if let Some((host, port)) = authority.rsplit_once(':') {
        let host = host.trim().trim_start_matches('[').trim_end_matches(']');
        let port = port
            .parse::<u16>()
            .map_err(|_| HealthHttpProbeError::InvalidOrigin)?;
        if host.is_empty() || port == 0 {
            return Err(HealthHttpProbeError::InvalidOrigin);
        }
        Ok((host.to_string(), port))
    } else {
        Ok((authority.to_string(), 80))
    }
}

fn health_http_io_error(error: &std::io::Error) -> HealthHttpProbeError {
    if matches!(
        error.kind(),
        std::io::ErrorKind::TimedOut | std::io::ErrorKind::WouldBlock
    ) {
        HealthHttpProbeError::Timeout
    } else {
        HealthHttpProbeError::Unreachable
    }
}

fn bounded_local_http_request(
    origin: &str,
    method: &str,
    path: &str,
    body: &str,
    timeout: Duration,
    headers: &[(&str, &str)],
) -> Result<CaptureProxyResponse, HealthHttpProbeError> {
    if !matches!(method, "GET" | "POST") {
        return Err(HealthHttpProbeError::InvalidResponse);
    }
    let (host, port) = health_http_origin_endpoint(origin)?;
    let deadline = Instant::now()
        .checked_add(timeout)
        .ok_or(HealthHttpProbeError::Timeout)?;
    let addresses = (host.as_str(), port)
        .to_socket_addrs()
        .map_err(|_| HealthHttpProbeError::Unreachable)?;
    let mut stream = None;
    for address in addresses {
        let remaining = deadline
            .checked_duration_since(Instant::now())
            .ok_or(HealthHttpProbeError::Timeout)?;
        if remaining.is_zero() {
            return Err(HealthHttpProbeError::Timeout);
        }
        if let Ok(candidate) = TcpStream::connect_timeout(&address, remaining) {
            stream = Some(candidate);
            break;
        }
    }
    let mut stream = stream.ok_or(HealthHttpProbeError::Unreachable)?;
    let remaining = deadline
        .checked_duration_since(Instant::now())
        .ok_or(HealthHttpProbeError::Timeout)?;
    stream
        .set_write_timeout(Some(remaining))
        .map_err(|error| health_http_io_error(&error))?;
    stream
        .set_read_timeout(Some(remaining))
        .map_err(|error| health_http_io_error(&error))?;
    let path = if path.starts_with('/') { path } else { "/" };
    let mut extra_headers = String::new();
    for (name, value) in headers {
        if name.is_empty()
            || !name
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
            || value.contains(['\r', '\n'])
        {
            return Err(HealthHttpProbeError::InvalidResponse);
        }
        extra_headers.push_str(name);
        extra_headers.push_str(": ");
        extra_headers.push_str(value);
        extra_headers.push_str("\r\n");
    }
    let request = format!(
        "{method} {path} HTTP/1.1\r\nHost: {host}:{port}\r\nConnection: close\r\nAccept: application/json\r\nContent-Type: application/json\r\n{extra_headers}Content-Length: {}\r\n\r\n{}",
        body.as_bytes().len(),
        body
    );
    stream
        .write_all(request.as_bytes())
        .map_err(|error| health_http_io_error(&error))?;

    let mut response = Vec::new();
    let mut buffer = [0_u8; 8192];
    loop {
        let remaining = deadline
            .checked_duration_since(Instant::now())
            .ok_or(HealthHttpProbeError::Timeout)?;
        if remaining.is_zero() {
            return Err(HealthHttpProbeError::Timeout);
        }
        stream
            .set_read_timeout(Some(remaining))
            .map_err(|error| health_http_io_error(&error))?;
        match stream.read(&mut buffer) {
            Ok(0) => break,
            Ok(count) => {
                response.extend_from_slice(&buffer[..count]);
                if response.len() > HEALTH_HTTP_MAX_RESPONSE_BYTES {
                    return Err(HealthHttpProbeError::InvalidResponse);
                }
            }
            Err(error) => return Err(health_http_io_error(&error)),
        }
    }
    parse_capture_http_response(response).ok_or(HealthHttpProbeError::InvalidResponse)
}

fn bounded_health_http_get(
    origin: &str,
    path: &str,
    timeout: Duration,
) -> Result<CaptureProxyResponse, HealthHttpProbeError> {
    bounded_local_http_request(origin, "GET", path, "", timeout, &[])
}

fn database_health_component(state: &ServiceState) -> (bool, Value) {
    let started = Instant::now();
    let ok = state
        .runtime
        .block_on(state.database.connection.ping())
        .is_ok();
    (
        ok,
        json!({
            "ok": ok,
            "status": if !ok { "unavailable" } else if state.database.fallback_active { "degraded" } else { "up" },
            "engine": state.database.engine.clone(),
            "requestedEngine": state.database.requested_engine.clone(),
            "supportedEngines": state.database.supported_engines(),
            "fallbackEnabled": state.database.fallback_enabled,
            "fallbackActive": state.database.fallback_active,
            "fallbackReason": state.database.fallback_reason.clone(),
            "schemaVersion": state.database.schema_version,
            "latencyMs": health_latency_ms(started),
            "reason": if ok { Value::Null } else { json!("database_ping_failed") }
        }),
    )
}

fn task_worker_health_component(state: &ServiceState) -> (bool, Value) {
    let status = match state.production_task_worker_status.lock() {
        Ok(status) => status.clone(),
        Err(_) => {
            return (
                false,
                json!({
                    "ok": false,
                    "status": "unavailable",
                    "running": false,
                    "busy": false,
                    "heartbeatFresh": false,
                    "heartbeatAgeMs": Value::Null,
                    "heartbeatPausedAtProviderBoundary": false,
                    "reason": "task_worker_status_lock_poisoned"
                }),
            );
        }
    };
    let now = current_time_millis();
    let heartbeat_age = status
        .last_heartbeat_at
        .checked_sub(0)
        .filter(|value| *value > 0)
        .map(|_| now.saturating_sub(status.last_heartbeat_at));
    let heartbeat_fresh = heartbeat_age
        .map(|age| age <= TASK_WORKER_IDLE_HEARTBEAT_MAX_AGE_MS)
        .unwrap_or(false);
    let busy = !status.current_task_id.is_empty();

    // Task execution currently crosses a synchronous provider boundary. While a task is active,
    // the worker cannot refresh its own heartbeat, so running+busy is reported honestly as busy
    // instead of being treated as a stale idle worker.
    let ok = status.running && (busy || heartbeat_fresh);
    let reason = if !status.running {
        Some("task_worker_not_running")
    } else if !busy && !heartbeat_fresh {
        Some("task_worker_heartbeat_stale")
    } else {
        None
    };
    (
        ok,
        json!({
            "ok": ok,
            "status": if ok && busy { "busy" } else if ok { "idle" } else { "unavailable" },
            "running": status.running,
            "busy": busy,
            "heartbeatFresh": heartbeat_fresh,
            "heartbeatAgeMs": heartbeat_age,
            "heartbeatPausedAtProviderBoundary": busy,
            "recoveredTasks": status.recovered_tasks,
            "reason": reason
        }),
    )
}

