fn unified_record_status(status: &str) -> &'static str {
    match status {
        "partial" | "processing" | "running" | "pending" => "detecting",
        _ => "completed",
    }
}

fn unified_defect_severity(severity: Option<i64>) -> &'static str {
    match severity {
        Some(value) if value >= 3 => "severe",
        Some(1) => "minor",
        _ => "review",
    }
}

fn unified_record_json(
    record: &standard_record_store::InspectionRecordDto,
    defects: &[standard_record_store::InspectionDefectDto],
) -> Value {
    let severe = defects
        .iter()
        .filter(|defect| unified_defect_severity(defect.severity) == "severe")
        .count() as u64;
    let minor = defects
        .iter()
        .filter(|defect| unified_defect_severity(defect.severity) == "minor")
        .count() as u64;
    let classified_review = defects
        .iter()
        .filter(|defect| unified_defect_severity(defect.severity) == "review")
        .count() as u64;
    let total = u64::try_from(record.defect_count.max(0)).unwrap_or(0);
    let review = classified_review.saturating_add(
        total.saturating_sub(
            severe
                .saturating_add(minor)
                .saturating_add(classified_review),
        ),
    );
    let inspection_time = record.inspection_time.as_deref().unwrap_or_default();
    json!({
        "id": record.record_id,
        "time": inspection_time,
        "plateNo": record.steel_id,
        "materialId": record.steel_id,
        "sessionId": format!("result-{}", record.record_id),
        "status": unified_record_status(&record.status),
        "productionStatus": record.status,
        "defectCount": total,
        "startedAt": inspection_time,
        "finishedAt": inspection_time,
        "summaryPath": Value::Null,
        "source": "unified-result",
        "sourceRevision": record.source_hash,
        "plate": {
            "plateNo": record.steel_id,
            "widthMm": record.outer_diameter_mm.unwrap_or(0.0),
            "lengthMm": record.length_mm.unwrap_or(0.0),
            "thicknessMm": record.wall_thickness_mm.unwrap_or(0.0),
            "steelGrade": record.steel_type.as_deref().unwrap_or("-"),
            "detectedAt": inspection_time,
        },
        "severity": {
            "severe": severe,
            "review": review,
            "minor": minor,
        }
    })
}

fn unified_record_detail_json(
    record: &standard_record_store::InspectionRecordDto,
    defects: &[standard_record_store::InspectionDefectDto],
) -> String {
    let mut value = unified_record_json(record, defects);
    if let Some(object) = value.as_object_mut() {
        object.insert(
            "defects".to_string(),
            Value::Array(
                defects
                    .iter()
                    .map(|defect| {
                        let roi = defect
                            .artifacts
                            .get("roi")
                            .or_else(|| defect.artifacts.get("imageRect2d"));
                        let width = roi
                            .and_then(|value| value.get("width"))
                            .and_then(Value::as_f64)
                            .or_else(|| {
                                let left = roi?.get("left")?.as_f64()?;
                                let right = roi?.get("right")?.as_f64()?;
                                Some((right - left).abs())
                            })
                            .unwrap_or(0.0);
                        let height = roi
                            .and_then(|value| value.get("height"))
                            .and_then(Value::as_f64)
                            .or_else(|| {
                                let top = roi?.get("top")?.as_f64()?;
                                let bottom = roi?.get("bottom")?.as_f64()?;
                                Some((bottom - top).abs())
                            })
                            .unwrap_or(0.0);
                        json!({
                            "id": defect.id,
                            "plateNo": record.steel_id,
                            "typeId": defect.defect_type,
                            "typeLabel": defect.defect_type,
                            "surface": defect.camera_id,
                            "severity": unified_defect_severity(defect.severity),
                            "distanceHeadMm": 0.0,
                            "operatorSideMm": 0.0,
                            "driveSideMm": 0.0,
                            "widthMm": width,
                            "heightMm": height,
                            "depthMm": 0.0,
                            "xRatio": 0.0,
                            "yOffsetMm": 0.0,
                            "previewX": 0,
                            "previewY": 0,
                            "artifacts": defect.artifacts,
                        })
                    })
                    .collect(),
            ),
        );
        object.insert("algorithmTrace".to_string(), Value::Null);
    }
    json!({ "record": value }).to_string()
}

fn read_admin_cameras_response(state: &ServiceState) -> Vec<u8> {
    match state
        .runtime
        .block_on(db::list_camera_configs(&state.database.connection))
    {
        Ok(cameras) => http_response(
            "200 OK",
            "application/json; charset=utf-8",
            &camera_configs_json(cameras),
        ),
        Err(error) => http_response(
            "500 Internal Server Error",
            "application/json; charset=utf-8",
            &format!("{{\"error\":\"{}\"}}", json_escape(&error.to_string())),
        ),
    }
}

fn reject_invalid_camera_config(
    state: &ServiceState,
    actor: &str,
    target: &str,
    detail: &str,
) -> Vec<u8> {
    let _ = state.runtime.block_on(db::append_audit_log(
        &state.database.connection,
        actor,
        "camera_config.validation.failed",
        target,
        detail,
        "warning",
    ));
    http_response(
        "400 Bad Request",
        "application/json; charset=utf-8",
        &json!({
            "code": 400,
            "error": "invalid camera config",
            "message": detail
        })
        .to_string(),
    )
}

fn camera_config_input_from_value(payload: &Value) -> Result<db::CameraConfigInput, String> {
    let object = object_value(payload, "camera")?;
    let id = validate_text_field(object, "id", "id", "camera", 64)?;
    let name = validate_text_field(object, "name", "name", "camera", 128)?;
    let ip = validate_text_field(object, "ip", "ip", "camera", 255)?;
    let driver_id = optional_text_field_or_default(
        object,
        "driverId",
        "driver_id",
        "camera",
        64,
        "lvm-nvt".to_string(),
    )?;
    let model_hint = optional_text_field_or_default(
        object,
        "modelHint",
        "model_hint",
        "camera",
        128,
        "LVM3450CA".to_string(),
    )?;
    let role = optional_text_field_or_default(
        object,
        "role",
        "role",
        "camera",
        64,
        "采集相机".to_string(),
    )?;
    let enabled = optional_bool_field_or_default(object, "enabled", "enabled", "camera", true)?;
    let trigger_mode = optional_text_field_or_default(
        object,
        "triggerMode",
        "trigger_mode",
        "camera",
        64,
        "软件触发".to_string(),
    )?;
    let exposure_us = optional_i64_field_or_default(
        object,
        "exposureUs",
        "exposure_us",
        "camera",
        1,
        1_000_000,
        850,
    )? as i32;
    let gain = optional_f64_field_or_default(object, "gain", "gain", "camera", 0.0, 100.0, 1.0)?;
    let depth_lines = optional_i64_field_or_default(
        object,
        "depthLines",
        "depth_lines",
        "camera",
        1,
        100_000,
        1280,
    )? as i32;
    let output_path = optional_text_field_or_default(
        object,
        "outputPath",
        "output_path",
        "camera",
        260,
        format!("captures/{id}"),
    )?;

    Ok(db::CameraConfigInput {
        id,
        name,
        ip,
        driver_id,
        model_hint,
        role,
        enabled,
        trigger_mode,
        exposure_us,
        gain,
        depth_lines,
        output_path,
    })
}

