    #[test]
    fn production_algorithm_traceability_requires_identity_hashes_inputs_thresholds_and_gate() {
        let sha = "a".repeat(64);
        let artifact = json!({
            "camera": "camera1",
            "frameId": "frame-001",
            "kind": "depth",
            "path": r"H:\camera1\plate\depth\frame-001.png",
            "bytes": 42,
            "sha256": "d".repeat(64)
        });
        let input_summary =
            canonical_value_sha256(&json!([artifact.clone()])).expect("canonical input hash");
        assert_eq!(
            input_summary,
            "eaf4f395409243cfebeadb938c63b5b64afeec6e3162c27b7e188e09b0441a53"
        );
        let valid = json!({
            "result": { "manifest": {
                "algorithmName": "bar-surface-defect-detector",
                "algorithmVersion": "bar-surface-radial-residual-1.0.0",
                "configRevision": "ALGCFG-1",
                "configSha256": sha,
                "calibrationRevision": "CAL-1",
                "calibrationSha256": "b".repeat(64),
                "scriptSha256": "e".repeat(64),
                "coreSha256": "f".repeat(64),
                "acceptanceReportSha256": "1".repeat(64),
                "datasetRevision": "DATASET-1",
                "datasetSha256": "2".repeat(64),
                "evaluatorRevision": "EVALUATOR-1",
                "evaluatorSha256": "3".repeat(64),
                "releaseCommit": "4".repeat(40),
                "inputSummarySha256": input_summary,
                "inputFrameIds": ["frame-001"],
                "inputArtifactCount": 1,
                "inputArtifacts": [artifact],
                "thresholds": {
                    "meshRows": 144,
                    "meshColsPerCamera": 72,
                    "radiusMm": 75.0,
                    "radialScaleMm": 8.0,
                    "maxFaceEdgeMm": 8.0,
                    "contourRadiusToleranceMm": 0.0,
                    "contourMinKeepRatio": 0.55,
                    "contourMinRowCoverage": 0.25,
                    "contourAutoPercentile": 96.0,
                    "defectMinDepthMm": 0.35,
                    "defectMinAreaPoints": 6
                },
                "qualityGate": { "passed": true, "reasons": [] },
                "core": { "available": true, "summary": { "outputBytes": 128 } },
                "realDefectCount": 0,
                "syntheticDefectCount": 0
            }}
        });
        assert_eq!(
            algorithm_traceability_structure_error(&valid["result"]["manifest"]),
            None
        );

        let mut bad_hash = valid.clone();
        bad_hash["result"]["manifest"]["inputSummarySha256"] = json!("not-a-hash");
        assert_eq!(
            algorithm_traceability_structure_error(&bad_hash["result"]["manifest"]),
            Some("algorithm_traceability_sha256_missing".to_string())
        );

        let mut failed_gate = valid;
        failed_gate["result"]["manifest"]["qualityGate"]["passed"] = json!(false);
        assert_eq!(
            algorithm_traceability_structure_error(&failed_gate["result"]["manifest"]),
            Some("algorithm_quality_gate_failed".to_string())
        );
    }

    #[test]
    fn automatic_calibration_activation_requires_target_quality_and_opt_in() {
        assert_eq!(
            automatic_calibration_activation_decision(
                &json!({ "targetDetection": { "detected": false }, "correctionAccepted": true }),
                true,
            ),
            (false, true, "calibration_target_not_detected")
        );
        assert_eq!(
            automatic_calibration_activation_decision(
                &json!({ "targetDetection": { "detected": true }, "correctionAccepted": false }),
                true,
            ),
            (true, false, "correction_quality_gate_failed")
        );
        assert_eq!(
            automatic_calibration_activation_decision(
                &json!({ "targetDetection": { "detected": true }, "correctionAccepted": true }),
                false,
            ),
            (true, true, "automatic_activation_disabled")
        );
        assert_eq!(
            automatic_calibration_activation_decision(
                &json!({ "targetDetection": { "detected": true }, "correctionAccepted": true }),
                true,
            ),
            (true, true, "pending")
        );
    }

    #[test]
    fn admin_identifier_validation_rejects_unstable_ids() {
        assert!(validate_admin_identifier("supervisor-01", "adminUser.id").is_ok());
        assert!(validate_admin_identifier("reviewer.main", "role.id").is_ok());

        let starts_with_dash = validate_admin_identifier("-reviewer", "role.id").unwrap_err();
        assert!(starts_with_dash.contains("必须以字母或数字开头"));

        let contains_space = validate_admin_identifier("bad role", "role.id").unwrap_err();
        assert!(contains_space.contains("只能包含字母"));

        let too_long =
            validate_admin_identifier(&"a".repeat(ADMIN_ID_MAX_LEN + 1), "role.id").unwrap_err();
        assert!(too_long.contains("长度不能超过"));
    }

    fn converted_world_fixture() -> (PathBuf, standard_record_store::ConvertedLocalStore) {
        let sequence = CONVERTED_WORLD_FIXTURE_SEQUENCE.fetch_add(1, Ordering::Relaxed);
        let root = std::env::temp_dir().join(format!(
            "steel-converted-world-{}-{}-{}",
            std::process::id(),
            current_time_millis(),
            sequence
        ));
        let record_root = root.join("records").join("10");
        fs::create_dir_all(&record_root).expect("converted record root");
        fs::write(
            record_root.join("record.json"),
            r#"{"schema":"steel.standard-record.v2"}"#,
        )
        .expect("converted record marker");
        let catalog = root.join("catalog.db");
        let connection = rusqlite::Connection::open(&catalog).expect("converted catalog");
        connection
            .execute_batch(
                r#"
                CREATE TABLE production_inspection (
                    id TEXT PRIMARY KEY, session_id TEXT NOT NULL,
                    material_id TEXT NOT NULL, inspection_time TEXT,
                    status TEXT NOT NULL, defect_count INTEGER NOT NULL,
                    camera_count INTEGER NOT NULL, source_hash TEXT NOT NULL,
                    record_path TEXT NOT NULL, metadata_json TEXT NOT NULL,
                    generation INTEGER NOT NULL
                );
                CREATE TABLE production_defect (
                    id TEXT PRIMARY KEY, inspection_id TEXT NOT NULL,
                    camera_id TEXT NOT NULL, sequence_no INTEGER NOT NULL,
                    defect_type TEXT NOT NULL, severity INTEGER,
                    confidence REAL, artifacts_json TEXT NOT NULL
                );
                CREATE TABLE capture_file (
                    id TEXT PRIMARY KEY, inspection_id TEXT NOT NULL,
                    camera_id TEXT NOT NULL, sequence_no INTEGER NOT NULL,
                    kind TEXT NOT NULL, path TEXT NOT NULL, size INTEGER NOT NULL,
                    sha256 TEXT NOT NULL
                );
                INSERT INTO production_inspection VALUES (
                    '10', 'bkv-10', 'STEEL-10', '2025-09-26 03:36:17',
                    'legacy-imported', 1, 6, 'record-hash', 'records/10',
                    '{"steelType":"37Mn/2","lengthMm":12096,"outerDiameterLegacyValue":233.664,"wallThicknessMm":12.5}',
                    7
                );
                INSERT INTO production_defect VALUES (
                    '10-100', '10', 'C1', 4, '轧折', 1, 51,
                    '{"imageRect2d":{"left":0,"right":2,"top":0,"bottom":1}}'
                );
                "#,
            )
            .expect("converted fixture schema");
        for camera_id in 1..=6 {
            let relative = format!("records/10/cameras/C{camera_id}/intensity/000004.jpg");
            let path = root.join(&relative);
            fs::create_dir_all(path.parent().expect("frame parent")).expect("frame parent");
            image::RgbImage::from_pixel(32, 48, image::Rgb([camera_id as u8 * 20, 80, 100]))
                .save(&path)
                .expect("converted intensity");
            let mut digest = Sha256::new();
            digest.update(fs::read(&path).expect("intensity bytes"));
            connection
                .execute(
                    "INSERT INTO capture_file VALUES (?, '10', ?, 4, 'intensity', ?, ?, ?)",
                    rusqlite::params![
                        format!("10-C{camera_id}-4-intensity"),
                        format!("C{camera_id}"),
                        relative,
                        path.metadata().expect("intensity metadata").len(),
                        format!("{:x}", digest.finalize()),
                    ],
                )
                .expect("capture file");
        }
        drop(connection);
        let store = standard_record_store::ConvertedLocalStore::open(
            &root,
            &catalog,
            (1..=6)
                .map(|camera_id| standard_record_store::ConfiguredCamera {
                    id: format!("C{camera_id}"),
                    display_order: camera_id,
                    source_camera_id: camera_id as u32,
                })
                .collect(),
        )
        .expect("converted store");
        (root, store)
    }

